/** Rust: `win_theme::WindowsThemeInfo` */
export interface WindowsThemeInfo {
  accentHex: string;
  accentR: number;
  accentG: number;
  accentB: number;
  appsUseLightTheme: boolean;
  systemUsesLightTheme: boolean;
  transparencyEnabled: boolean;
  /** "windows" | "macos" | "linux" */
  osFamily: string;
  /** Windows build number (e.g. 19045 = Windows 10 22H2, 22631 = Windows 11 23H2); 0 elsewhere. */
  windowsBuild: number;
  /** Window styling Lens can apply on this system (see `os_features`). */
  osFeatures: OsFeatures;
}

/**
 * Result of talking to the Windows notification listener.
 * Rust: `win_notifications::WindowsToastResult`
 */
export interface WindowsToastResult {
  /** "ok" | "needs-access" | "denied" | "unavailable" */
  status: string;
  /** Plain-language explanation when status is not "ok" (empty otherwise). */
  reason: string;
  items: NotificationItem[];
}

/** Rust: `win_training::WorkflowMacro` */
export interface WorkflowMacro {
  id: string;
  name: string;
  createdAt: number;
  steps: WorkflowMacroStep[];
}

/** Rust: `win_training::WorkflowMacroStep` */
export interface WorkflowMacroStep {
  kind: string;
  label: string;
  payload: string;
}

/** Rust: `win_workspaces::WorkspaceDef` */
export interface WorkspaceDef {
  id: string;
  name: string;
  color: string;
  /** Tiling layout for this workspace; "" uses the global tiling layout. */
  layout: string;
  /** Apps that open on this workspace (process names, e.g. "spotify.exe"). */
  apps: string[];
  /** Apps that always float while on this workspace. */
  floatApps: string[];
}

/** Rust: `win_workspaces::WorkspaceStatus` */
export interface WorkspaceStatus {
  enabled: boolean;
  /** Backend in use: "virtual-desktops" | "groups". */
  mode: string;
  active: number;
  workspaces: WorkspaceView[];
  /** Number of Windows virtual desktops (virtual-desktops mode). */
  desktopCount: number;
  appRulesActive: boolean;
  /** Plain-language explanation of any limitation. */
  note: string;
}

/** Rust: `win_workspaces::WorkspaceView` */
export interface WorkspaceView {
  index: number;
  id: string;
  name: string;
  color: string;
  layout: string;
  /** Known only in groups mode. */
  windowCount: number | null;
}

/** Rust: `win_workspaces::WorkspacesConfig` */
export interface WorkspacesConfig {
  enabled: boolean;
  /** "auto" | "virtual-desktops" | "groups" */
  mode: string;
  /** When an app with a rule opens, switch to its workspace (true) or leave it there minimised. */
  followAssigned: boolean;
  workspaces: WorkspaceDef[];
}

